import {isFeatureEnabled} from '@github-ui/feature-flags'
import {Filter, FILTER_PRIORITY_DISPLAY_THRESHOLD, type FilterSuggestion, FilterValueType} from '@github-ui/filter'
import {
  AssigneeFilterProvider,
  IsFilterProvider,
  LabelFilterProvider,
  MilestoneFilterProvider,
  RepositoryFilterProvider,
  StateFilterProvider,
} from '@github-ui/filter/providers'
import {TypeFilterProvider} from '@github-ui/filter/providers/type'
import {type ColorName, type ColorSet, useGetPresentationalColor} from '@github-ui/use-named-color'
import {memo, useCallback, useMemo, useRef} from 'react'
import {type Environment, useRelayEnvironment} from 'react-relay'

import {MemexColumnDataType} from '../../api/columns/contracts/memex-column'
import {getEnabledFeatures} from '../../helpers/feature-flags'
import {getInitialState} from '../../helpers/initial-state'
import type {LoggedInUser} from '../../helpers/json-island'
import {useEnabledFeatures} from '../../hooks/use-enabled-features'
import type {ColumnModel} from '../../models/column-model'
import {useAllColumns} from '../../state-providers/columns/use-all-columns'
import {Resources} from '../../strings'
import styles from './filter-bar.module.css'
import {
  DateFilterProvider,
  FILTER_PRIORITIES,
  IterationFilterProvider,
  LastUpdatedFilterProvider,
  LinkedPullRequestsFilterProvider,
  MemexAssigneeFilterProvider,
  MemexLabelFilterProvider,
  MemexMilestoneFilterProvider,
  MemexParentIssueFilterProvider,
  MemexRepositoryFilterProvider,
  MemexReviewersFilterProvider,
  MemexTypeFilterProvider,
  MemexUpdatedFilterProvider,
  NumberFilterProvider,
  ReasonFilterProvider,
  ReviewersFilterProvider,
  SingleSelectFilterProvider,
  SubIssuesProgressFilterProvider,
  TextFilterProvider,
} from './filter-providers'
import {HasFilterProvider} from './has-filter-provider'
import {useHandleFilterBarShortcut} from './use-handle-filter-bar-shortcut'

type FilterBarProps = {
  value?: string
  onChange: (value: string) => void
}

const SUPPORTED_FILTER_TYPES: Array<MemexColumnDataType> = [
  MemexColumnDataType.Assignees,
  MemexColumnDataType.Date,
  MemexColumnDataType.Iteration,
  MemexColumnDataType.Labels,
  MemexColumnDataType.LinkedPullRequests,
  MemexColumnDataType.Milestone,
  MemexColumnDataType.IssueType,
  MemexColumnDataType.Number,
  MemexColumnDataType.Repository,
  MemexColumnDataType.Reviewers,
  MemexColumnDataType.SingleSelect,
  MemexColumnDataType.Text,
]

const getFilterProviderForColumn = (
  column: ColumnModel,
  getPresentationalColor: (color: ColorName) => ColorSet,
  loggedInUser?: LoggedInUser,
  relayEnvironment?: Environment,
  issue_types?: boolean,
  projectOwnerLogin?: string,
  projectNumber?: number,
  hasFilterEnabled?: boolean,
) => {
  const {memex_mwl_unique_filter_suggestions, memex_mwl_use_type_provider} = getEnabledFeatures()
  if (memex_mwl_unique_filter_suggestions) {
    return getFilterProviderForColumnWithUniqueFilterSuggestions(
      column,
      getPresentationalColor,
      loggedInUser,
      relayEnvironment,
      issue_types,
      projectOwnerLogin,
      projectNumber,
      hasFilterEnabled,
      memex_mwl_use_type_provider,
    )
  } else {
    return getFilterProviderForColumnWithoutUniqueFilterSuggestions(
      column,
      getPresentationalColor,
      loggedInUser,
      relayEnvironment,
      issue_types,
      projectOwnerLogin,
      projectNumber,
      hasFilterEnabled,
    )
  }
}

const getFilterProviderForColumnWithoutUniqueFilterSuggestions = (
  column: ColumnModel,
  getPresentationalColor: (color: ColorName) => ColorSet,
  loggedInUser?: LoggedInUser,
  relayEnvironment?: Environment,
  issue_types?: boolean,
  projectOwnerLogin?: string,
  projectNumber?: number,
  hasFilterEnabled?: boolean,
) => {
  const userFilterParams = loggedInUser
    ? {
        showAtMe: true,
        currentUserLogin: loggedInUser.login,
        currentUserAvatarUrl: loggedInUser.avatarUrl,
      }
    : {showAtMe: false}

  switch (column.dataType) {
    case MemexColumnDataType.Assignees:
      return new AssigneeFilterProvider(userFilterParams, {filterTypes: {exclusive: true, hasValue: hasFilterEnabled}})
    case MemexColumnDataType.Date:
      return new DateFilterProvider(column)
    case MemexColumnDataType.Iteration:
      return new IterationFilterProvider(column)
    case MemexColumnDataType.Labels:
      return new LabelFilterProvider({
        filterTypes: {exclusive: true, hasValue: hasFilterEnabled},
      })
    case MemexColumnDataType.LinkedPullRequests:
      return new LinkedPullRequestsFilterProvider()
    case MemexColumnDataType.Milestone:
      return new MilestoneFilterProvider({
        priority: FILTER_PRIORITIES.milestone,
        filterTypes: {exclusive: true, hasValue: hasFilterEnabled},
      })
    case MemexColumnDataType.IssueType:
      return new TypeFilterProvider(
        {priority: FILTER_PRIORITIES.type, filterTypes: {valueless: true, hasValue: hasFilterEnabled}},
        false,
        relayEnvironment,
        undefined,
        issue_types,
        {login: projectOwnerLogin, projectNumber},
      )
    case MemexColumnDataType.Number:
      return new NumberFilterProvider(column)
    case MemexColumnDataType.Repository:
      return new RepositoryFilterProvider({filterTypes: {exclusive: true, hasValue: hasFilterEnabled}})
    case MemexColumnDataType.Reviewers:
      return new ReviewersFilterProvider(userFilterParams, {filterTypes: {exclusive: true, hasValue: hasFilterEnabled}})
    case MemexColumnDataType.SingleSelect: {
      return new SingleSelectFilterProvider(column, getPresentationalColor)
    }
    case MemexColumnDataType.SubIssuesProgress:
      return new SubIssuesProgressFilterProvider(column, {filterTypes: {hasValue: hasFilterEnabled}})
    case MemexColumnDataType.Text:
      return new TextFilterProvider(column)
    case MemexColumnDataType.ParentIssue:
      return new MemexParentIssueFilterProvider(column, {filterTypes: {hasValue: hasFilterEnabled}})
    default:
      throw new Error(`Filter support for ${column.name} column not implemented`)
  }
}

const getFilterProviderForColumnWithUniqueFilterSuggestions = (
  column: ColumnModel,
  getPresentationalColor: (color: ColorName) => ColorSet,
  loggedInUser?: LoggedInUser,
  relayEnvironment?: Environment,
  issue_types?: boolean,
  projectOwnerLogin?: string,
  projectNumber?: number,
  hasFilterEnabled?: boolean,
  useStandardTypeProvider?: boolean,
) => {
  const userFilterParams = loggedInUser
    ? {
        showAtMe: true,
        currentUserLogin: loggedInUser.login,
        currentUserAvatarUrl: loggedInUser.avatarUrl,
      }
    : {showAtMe: false}

  switch (column.dataType) {
    case MemexColumnDataType.Assignees:
      return new MemexAssigneeFilterProvider(column, userFilterParams, {
        filterTypes: {exclusive: true, hasValue: hasFilterEnabled},
      })
    case MemexColumnDataType.Date:
      return new DateFilterProvider(column)
    case MemexColumnDataType.Iteration:
      return new IterationFilterProvider(column)
    case MemexColumnDataType.Labels:
      return new MemexLabelFilterProvider(column, {
        filterTypes: {exclusive: true, hasValue: hasFilterEnabled},
      })
    case MemexColumnDataType.LinkedPullRequests:
      return new LinkedPullRequestsFilterProvider({
        filterTypes: {hasValue: hasFilterEnabled},
      })
    case MemexColumnDataType.Milestone:
      return new MemexMilestoneFilterProvider(column, {
        priority: FILTER_PRIORITIES.milestone,
        filterTypes: {exclusive: true, hasValue: hasFilterEnabled},
      })
    case MemexColumnDataType.IssueType:
      if (useStandardTypeProvider) {
        return new TypeFilterProvider(
          {priority: FILTER_PRIORITIES.type, filterTypes: {valueless: true, hasValue: hasFilterEnabled}},
          false,
          relayEnvironment,
          undefined,
          issue_types,
          {login: projectOwnerLogin, projectNumber},
        )
      }
      return new MemexTypeFilterProvider(
        column,
        {priority: FILTER_PRIORITIES.type, filterTypes: {valueless: true, hasValue: hasFilterEnabled}},
        false,
        relayEnvironment,
        undefined,
        issue_types,
        {login: projectOwnerLogin, projectNumber},
      )
    case MemexColumnDataType.Number:
      return new NumberFilterProvider(column)
    case MemexColumnDataType.Repository:
      return new MemexRepositoryFilterProvider(column, {filterTypes: {exclusive: true, hasValue: hasFilterEnabled}})
    case MemexColumnDataType.Reviewers:
      return new MemexReviewersFilterProvider(column, userFilterParams, {
        filterTypes: {exclusive: true, hasValue: hasFilterEnabled},
      })
    case MemexColumnDataType.SingleSelect:
      return new SingleSelectFilterProvider(column, getPresentationalColor)
    case MemexColumnDataType.SubIssuesProgress:
      return new SubIssuesProgressFilterProvider(column, {filterTypes: {hasValue: hasFilterEnabled}})
    case MemexColumnDataType.Text:
      return new TextFilterProvider(column)
    case MemexColumnDataType.ParentIssue:
      return new MemexParentIssueFilterProvider(column, {filterTypes: {hasValue: hasFilterEnabled}})
    default:
      throw new Error(`Filter support for ${column.name} column not implemented`)
  }
}

export const FilterBar = memo(function FilterBar({value, onChange}: FilterBarProps) {
  const relayEnvironment = useRelayEnvironment()

  const {issue_types, sub_issues, memex_table_without_limits} = useEnabledFeatures()
  const hasFilterEnabled = isFeatureEnabled('issues_advanced_search_has_filter')
  const {allColumns} = useAllColumns()
  const {loggedInUser, projectOwner, projectData} = getInitialState()
  const {mwl_filter_bar_validation} = useEnabledFeatures()
  const {getPresentationalColor} = useGetPresentationalColor()
  const columnFilterProviders = useMemo(() => {
    const supportedFilterTypes = [...SUPPORTED_FILTER_TYPES]
    if (sub_issues) {
      supportedFilterTypes.push(MemexColumnDataType.ParentIssue)
      supportedFilterTypes.push(MemexColumnDataType.SubIssuesProgress)
    }
    return allColumns
      .filter(({dataType}) => supportedFilterTypes.includes(dataType))
      .map(column =>
        getFilterProviderForColumn(
          column,
          getPresentationalColor,
          loggedInUser,
          relayEnvironment,
          issue_types,
          projectOwner?.login,
          projectData?.number,
          hasFilterEnabled,
        ),
      )
  }, [
    sub_issues,
    allColumns,
    loggedInUser,
    relayEnvironment,
    issue_types,
    projectOwner?.login,
    projectData?.number,
    hasFilterEnabled,
    getPresentationalColor,
  ])

  const inputRef = useRef<HTMLInputElement>(null)

  const onFilterBarShortcut = useCallback(() => {
    inputRef.current?.focus()
  }, [])

  useHandleFilterBarShortcut(onFilterBarShortcut)

  const newHasFilterEnabled = isFeatureEnabled('issues_advanced_search_has_filter')

  const hasFilterProviderValues: Array<FilterSuggestion> = useMemo(
    () =>
      columnFilterProviders
        .sort((a, b) => (a.displayName ?? a.key)?.localeCompare(b.displayName ?? b.key) ?? 0)
        .filter(provider => provider.options.filterTypes.valueless !== false)
        .map(provider => ({
          value: provider.key,
          priority: FILTER_PRIORITY_DISPLAY_THRESHOLD,
          displayName: provider.displayName,
          type: FilterValueType.Value,
          icon: provider.icon,
        })),
    [columnFilterProviders],
  )

  return (
    <Filter
      id="filter-bar-component"
      data-testid="filter-bar-component"
      label="Filter"
      filterButtonVariant="compact"
      settings={{
        aliasMatching: true,
      }}
      variant={memex_table_without_limits ? 'input' : 'full'}
      aria-label={Resources.filterByKeyboardOrByField}
      placeholder={Resources.filterByKeyboardOrByField}
      filterValue={value}
      inputRef={inputRef}
      onChange={onChange}
      showValidationMessage={mwl_filter_bar_validation}
      providers={useMemo(
        () => [
          ...columnFilterProviders,
          new LastUpdatedFilterProvider(),
          new IsFilterProvider(['issue', 'pr', 'open', 'closed', 'draft', 'merged'], {filterTypes: {valueless: false}}),
          new StateFilterProvider('mixed', {
            priority: FILTER_PRIORITIES.state,
            filterTypes: {valueless: false},
          }),
          ...(newHasFilterEnabled ? [] : [new HasFilterProvider(hasFilterProviderValues)]), // if the feature flag to use the new 'has' filter is disabled, then don't include the custom memex HasFilterProvider
          new MemexUpdatedFilterProvider({filterTypes: {valueless: false}}),
          new ReasonFilterProvider(),
        ],
        [columnFilterProviders, hasFilterProviderValues, newHasFilterEnabled],
      )}
      className={styles.Filter_0}
    />
  )
})

try{ FilterBar.displayName ||= 'FilterBar' } catch {}